/**
 * Represents the outcome of a parsing attempt.
 * @typedef {object} ParsingOutcome
 * @property {number} newOffset - The position in the source text after a successful parse.
 * @property {*} parsedValue - The value extracted or generated by the parser.
 */

/**
 * Parses a single character from the input source text.
 * This is a fundamental utility function for character-level consumption.
 * @param {string} sourceText The complete input string being parsed.
 * @param {number} currentOffset The starting position for this parsing attempt.
 * @returns {ParsingOutcome|null} A ParsingOutcome object if a character is successfully consumed, otherwise null.
 */
function parseCharacter(sourceText, currentOffset) {
  // Ensure the current offset is within the bounds of the source text.
  if (currentOffset >= sourceText.length) {
    return null; // Cannot parse if at or beyond the end of the input.
  }
  // Return the character at the current offset and advance the position.
  return { newOffset: currentOffset + 1, parsedValue: sourceText.charAt(currentOffset) };
}

/**
 * Attempts to match a specific literal string at the current parsing offset.
 * @param {string} sourceText The complete input string.
 * @param {number} currentOffset The starting position for the match.
 * @param {string} targetString The literal string to find.
 * @returns {ParsingOutcome|null} A ParsingOutcome object if the target string is matched, otherwise null.
 */
function matchLiteralString(sourceText, currentOffset, targetString) {
  // Check if the substring starting at currentOffset matches the target string.
  if (sourceText.substring(currentOffset, currentOffset + targetString.length) === targetString) {
    // If matched, advance the offset by the length of the matched string.
    return { newOffset: currentOffset + targetString.length, parsedValue: targetString };
  } else {
    // No match found.
    return null;
  }
}

/**
 * Attempts to consume a single whitespace character (space, newline, or tab).
 * This function handles the 'OR' logic for different whitespace types.
 * @param {string} sourceText The input string.
 * @param {number} startOffset The initial parsing position.
 * @returns {ParsingOutcome|null} A ParsingOutcome object if any whitespace is matched, otherwise null.
 */
function consumeWhitespace(sourceText, startOffset) {
  // Store the initial offset for potential backtracking if alternatives fail.
  let recoveryPoint = startOffset;
  let matchedResult = null;

  // Try matching a space character.
  matchedResult = matchLiteralString(sourceText, recoveryPoint, ' ');
  if (matchedResult) {
    return matchedResult;
  }

  // If space failed, try matching a newline character.
  matchedResult = matchLiteralString(sourceText, recoveryPoint, '\n');
  if (matchedResult) {
    return matchedResult;
  }

  // If newline failed, try matching a tab character.
  matchedResult = matchLiteralString(sourceText, recoveryPoint, '\t');
  if (matchedResult) {
    return matchedResult;
  }

  // If no whitespace character was matched by any alternative.
  return null;
}

/**
 * Parses zero or more whitespace characters.
 * This function is always successful, returning a new offset even if no whitespace is consumed.
 * It uses an iterative approach for consuming sequential whitespace.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome} A ParsingOutcome object containing the new offset after consuming all found whitespace.
 */
function consumeZeroOrMoreWhitespace(sourceText, currentOffset) {
  let finalOffset = currentOffset; // Initialize with the starting offset.
  let singleWhitespaceMatch;

  // Continuously attempt to consume individual whitespace characters.
  while (true) {
    singleWhitespaceMatch = consumeWhitespace(sourceText, finalOffset);
    if (singleWhitespaceMatch) {
      // If a whitespace character was found, update the offset and continue the loop.
      finalOffset = singleWhitespaceMatch.newOffset;
    } else {
      // No more whitespace characters found, so break the loop.
      break;
    }
  }

  // Return the final offset, representing the position after all consumed whitespace.
  return { newOffset: finalOffset, parsedValue: '' };
}

/**
 * Identifies and parses any of the predefined meta-characters used in the grammar syntax.
 * This function iterates through a list of known meta-characters.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object if a meta-character is found, otherwise null.
 */
function identifyMetaCharacter(sourceText, currentOffset) {
  // Define all possible meta-character sequences.
  const metaSequences = ['!', "'", '<-', '/', '.', '(', ')', ':', '->'];
  let foundMetaChar = null;

  // Iterate through the list of meta-characters and attempt to match each one.
  for (const charSequence of metaSequences) {
    let currentAttempt = matchLiteralString(sourceText, currentOffset, charSequence);
    if (currentAttempt) {
      foundMetaChar = currentAttempt;
      break; // Stop at the first successful match.
    }
  }
  return foundMetaChar;
}

/**
 * Extracts a single valid character for a grammar rule identifier.
 * An identifier character is defined as any character that is not a meta-character and not a whitespace character.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the character if it's a valid identifier character, or null.
 */
function extractIdentifierChar(sourceText, currentOffset) {
  // Perform basic boundary check.
  if (currentOffset >= sourceText.length) {
    return null;
  }

  // Check if the character at currentOffset is a meta-character.
  const isMeta = identifyMetaCharacter(sourceText, currentOffset);
  if (isMeta) {
    return null; // Meta-characters are not allowed in identifiers.
  }

  // Check if the character at currentOffset is a whitespace character.
  const isWhitespace = consumeWhitespace(sourceText, currentOffset);
  if (isWhitespace) {
    return null; // Whitespace characters are not allowed in identifiers.
  }

  // If it's neither a meta-character nor whitespace, it's a valid identifier character.
  // Consume it as a generic character.
  const charResult = parseCharacter(sourceText, currentOffset);
  return charResult;
}

/**
 * Extracts a grammar rule identifier (name).
 * An identifier consists of one or more valid name characters.
 * This function uses an iterative approach to consume characters.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the identifier string, or null if no identifier found.
 */
function extractIdentifier(sourceText, currentOffset) {
  let collectedIdentifierChars = [];
  let charParseResult;
  let tempOffset = currentOffset;

  // Loop to consume one or more identifier characters.
  while (true) {
    charParseResult = extractIdentifierChar(sourceText, tempOffset);
    if (charParseResult) {
      collectedIdentifierChars.push(charParseResult.parsedValue);
      tempOffset = charParseResult.newOffset;
    } else {
      break; // No more identifier characters found.
    }
  }

  // An identifier must have at least one character.
  if (collectedIdentifierChars.length === 0) {
    return null;
  }

  // Return the concatenated identifier string and the new offset.
  return {
    newOffset: tempOffset,
    parsedValue: collectedIdentifierChars.join('')
  };
}

/**
 * Extracts the raw content of a string literal, handling escaped characters.
 * This function supports basic backslash escaping and stops at the next unescaped single quote.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome} A ParsingOutcome object with the extracted string content, always successful (can be empty string).
 */
function extractStringContents(sourceText, currentOffset) {
  let collectedCharacters = [];
  let tempCurrentPos = currentOffset;
  let charMatch;

  // Loop until the end of the input or a closing quote is found.
  while (tempCurrentPos < sourceText.length) {
    // Check for an escape sequence (backslash followed by any character).
    let escapeCharCheck = matchLiteralString(sourceText, tempCurrentPos, '\\');
    if (escapeCharCheck) {
      let escapedCharOutcome = parseCharacter(sourceText, escapeCharCheck.newOffset);
      if (escapedCharOutcome) {
        collectedCharacters.push(escapeCharCheck.parsedValue + escapedCharOutcome.parsedValue);
        tempCurrentPos = escapedCharOutcome.newOffset;
        continue; // Continue to the next character after the escape sequence.
      } else {
        // If a backslash is at the end of the string, treat it as a literal backslash.
        collectedCharacters.push(escapeCharCheck.parsedValue);
        tempCurrentPos = escapeCharCheck.newOffset;
        break; // Or error, depending on strictness. For now, break.
      }
    }

    // Check for the closing single quote, which marks the end of the string literal.
    let closingQuoteProbe = matchLiteralString(sourceText, tempCurrentPos, "'");
    if (closingQuoteProbe) {
      break; // Found the end of the string contents.
    }

    // If it's not an escape sequence and not a closing quote, it's a regular character.
    charMatch = parseCharacter(sourceText, tempCurrentPos);
    if (charMatch) {
      collectedCharacters.push(charMatch.parsedValue);
      tempCurrentPos = charMatch.newOffset;
    } else {
      // Should not happen if within bounds and not a quote/escape.
      break;
    }
  }

  // Return the collected string content and the final offset.
  return {
    newOffset: tempCurrentPos,
    parsedValue: collectedCharacters.join('')
  };
}

/**
 * Parses a string literal enclosed in single quotes.
 * Example: 'hello world'
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the generated JS code for matching the literal, or null on failure.
 */
function parseStringLiteral(sourceText, currentOffset) {
  let stringParseResult = { newOffset: currentOffset, parsedValue: undefined };

  // Step 1: Match the opening single quote.
  let openQuoteMatch = matchLiteralString(sourceText, stringParseResult.newOffset, "'");
  if (!openQuoteMatch) return null;
  stringParseResult.newOffset = openQuoteMatch.newOffset;

  // Step 2: Extract the contents of the string literal.
  let contentsOutcome = extractStringContents(sourceText, stringParseResult.newOffset);
  // extractStringContents always returns an object, even if empty.
  const stringValue = contentsOutcome.parsedValue;
  stringParseResult.newOffset = contentsOutcome.newOffset;

  // Step 3: Match the closing single quote.
  let closeQuoteMatch = matchLiteralString(sourceText, stringParseResult.newOffset, "'");
  if (!closeQuoteMatch) return null; // A string literal must be properly terminated.
  stringParseResult.newOffset = closeQuoteMatch.newOffset;

  // Step 4: Consume any optional trailing whitespace.
  let wsAfterString = consumeZeroOrMoreWhitespace(sourceText, stringParseResult.newOffset);
  stringParseResult.newOffset = wsAfterString.newOffset; // consumeZeroOrMoreWhitespace always succeeds.

  // Step 5: Generate the JavaScript code to match this literal string during runtime.
  // Note: For full robustness, `stringValue` should be escaped for JavaScript string literals.
  stringParseResult.parsedValue = `  currentParseResult = matchLiteralString(sourceText, currentParseResult.newOffset, '${stringValue}');\n`;

  return stringParseResult;
}

/**
 * Parses a reference to a non-terminal grammar rule.
 * This generates the JavaScript code to call the corresponding parser function.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the generated JS code, or null on failure.
 */
function parseNonTerminalReference(sourceText, currentOffset) {
  let nonTerminalParseOutcome = { newOffset: currentOffset, parsedValue: undefined };

  // Step 1: Extract the identifier for the non-terminal rule.
  let nameOutcome = extractIdentifier(sourceText, nonTerminalParseOutcome.newOffset);
  if (!nameOutcome) return null;
  const nonTerminalName = nameOutcome.parsedValue;
  nonTerminalParseOutcome.newOffset = nameOutcome.newOffset;

  // Step 2: Consume any optional trailing whitespace after the non-terminal name.
  let wsOutcome = consumeZeroOrMoreWhitespace(sourceText, nonTerminalParseOutcome.newOffset);
  nonTerminalParseOutcome.newOffset = wsOutcome.newOffset; // consumeZeroOrMoreWhitespace always succeeds.

  // Step 3: Generate the JavaScript code that invokes the parser function for this non-terminal.
  nonTerminalParseOutcome.parsedValue = `  currentParseResult = parse_${nonTerminalName}(sourceText, currentParseResult.newOffset);\n`;

  return nonTerminalParseOutcome;
}

/**
 * Parses a labeled expression, which assigns the result of a term to a variable.
 * Format: `label: term`
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the generated JS code, or null on failure.
 */
function parseLabeledExpression(sourceText, currentOffset) {
  let labeledParseOutcome = { newOffset: currentOffset, parsedValue: undefined };

  // Step 1: Extract the label identifier.
  let labelOutcome = extractIdentifier(sourceText, labeledParseOutcome.newOffset);
  if (!labelOutcome) return null;
  const labelIdentifier = labelOutcome.parsedValue;
  labeledParseOutcome.newOffset = labelOutcome.newOffset;

  // Step 2: Consume optional whitespace before the colon.
  let wsBeforeColon = consumeZeroOrMoreWhitespace(sourceText, labeledParseOutcome.newOffset);
  labeledParseOutcome.newOffset = wsBeforeColon.newOffset;

  // Step 3: Match the ':' separator.
  let colonMatch = matchLiteralString(sourceText, labeledParseOutcome.newOffset, ':');
  if (!colonMatch) return null;
  labeledParseOutcome.newOffset = colonMatch.newOffset;

  // Step 4: Consume optional whitespace after the colon.
  let wsAfterColon = consumeZeroOrMoreWhitespace(sourceText, labeledParseOutcome.newOffset);
  labeledParseOutcome.newOffset = wsAfterColon.newOffset;

  // Step 5: Parse the actual term that is being labeled.
  let termOutcome = parseExpressionTerm(sourceText, labeledParseOutcome.newOffset);
  if (!termOutcome) return null;
  const termExecutionCode = termOutcome.parsedValue;
  labeledParseOutcome.newOffset = termOutcome.newOffset;

  // Step 6: Generate the combined JavaScript code. This code executes the term
  // and then, if the term was successful, assigns its result to the label variable.
  labeledParseOutcome.parsedValue = `${termExecutionCode}  if (currentParseResult) { const ${labelIdentifier} = currentParseResult.parsedValue; }\n`;

  return labeledParseOutcome;
}

/**
 * Parses a negated expression, meaning the inner term must NOT match for this expression to succeed.
 * Format: `!term`
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the generated JS code, or null on failure.
 */
function parseNegatedExpression(sourceText, currentOffset) {
  let negationParseOutcome = { newOffset: currentOffset, parsedValue: undefined };

  // Step 1: Match the '!' negation operator.
  let notOperatorMatch = matchLiteralString(sourceText, negationParseOutcome.newOffset, '!');
  if (!notOperatorMatch) return null;
  negationParseOutcome.newOffset = notOperatorMatch.newOffset;

  // Step 2: Consume optional whitespace after the '!' operator.
  let wsAfterNot = consumeZeroOrMoreWhitespace(sourceText, negationParseOutcome.newOffset);
  negationParseOutcome.newOffset = wsAfterNot.newOffset;

  // Step 3: Parse the term that is being negated.
  let negatedTermOutcome = parseExpressionTerm(sourceText, negationParseOutcome.newOffset);
  if (!negatedTermOutcome) return null;
  const termCodeForNegation = negatedTermOutcome.parsedValue;
  negationParseOutcome.newOffset = negatedTermOutcome.newOffset;

  // Step 4: Generate the JavaScript code for the negation logic.
  // This involves saving the current parsing state, attempting to parse the term,
  // and then succeeding if the term failed, or failing if the term succeeded.
  negationParseOutcome.parsedValue = `  choiceBacktrackStack.push({ newOffset: currentParseResult.newOffset, parsedValue: currentParseResult.parsedValue });\n` +
                                     `  ${termCodeForNegation}` +
                                     `  if (currentParseResult) {\n` + // If the term *did* match...
                                     `    choiceBacktrackStack.pop();\n` + // Discard the saved state.
                                     `    currentParseResult = null; // Negation fails.\n` +
                                     `  } else {\n` + // If the term *did not* match...
                                     `    currentParseResult = choiceBacktrackStack.pop(); // Negation succeeds, restore previous state.\n` +
                                     `  }\n`;

  return negationParseOutcome;
}

/**
 * Parses a parenthesized expression, essentially grouping a choice expression.
 * Format: `( choice )`
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the generated JS code for the inner choice, or null on failure.
 */
function parseGroupedExpression(sourceText, currentOffset) {
  let groupParseOutcome = { newOffset: currentOffset, parsedValue: undefined };

  // Step 1: Match the opening parenthesis.
  let openParenMatch = matchLiteralString(sourceText, groupParseOutcome.newOffset, '(');
  if (!openParenMatch) return null;
  groupParseOutcome.newOffset = openParenMatch.newOffset;

  // Step 2: Consume optional whitespace after the opening parenthesis.
  let ws1 = consumeZeroOrMoreWhitespace(sourceText, groupParseOutcome.newOffset);
  groupParseOutcome.newOffset = ws1.newOffset;

  // Step 3: Parse the inner choice expression.
  let innerChoiceOutcome = processRuleBodyChoices(sourceText, groupParseOutcome.newOffset);
  if (!innerChoiceOutcome) return null;
  const innerChoiceCode = innerChoiceOutcome.parsedValue;
  groupParseOutcome.newOffset = innerChoiceOutcome.newOffset;

  // Step 4: Consume optional whitespace before the closing parenthesis.
  let ws2 = consumeZeroOrMoreWhitespace(sourceText, groupParseOutcome.newOffset);
  groupParseOutcome.newOffset = ws2.newOffset;

  // Step 5: Match the closing parenthesis.
  let closeParenMatch = matchLiteralString(sourceText, groupParseOutcome.newOffset, ')');
  if (!closeParenMatch) return null;
  groupParseOutcome.newOffset = closeParenMatch.newOffset;

  // The generated code for a grouped expression is simply the code for its inner choice.
  groupParseOutcome.parsedValue = innerChoiceCode;

  return groupParseOutcome;
}


/**
 * Parses a result action expression, typically `-> { return some_value; }`.
 * This extracts the JavaScript code block and embeds it into the generated parser.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the generated JS code, or null on failure.
 */
function parseResultAction(sourceText, currentOffset) {
  let actionParseOutcome = { newOffset: currentOffset, parsedValue: undefined };

  // Step 1: Match the '->' arrow operator.
  let arrowMatch = matchLiteralString(sourceText, actionParseOutcome.newOffset, '->');
  if (!arrowMatch) return null;
  actionParseOutcome.newOffset = arrowMatch.newOffset;

  // Step 2: Consume optional whitespace after the arrow.
  let wsAfterArrow = consumeZeroOrMoreWhitespace(sourceText, actionParseOutcome.newOffset);
  actionParseOutcome.newOffset = wsAfterArrow.newOffset;

  // Step 3: Extract the JavaScript code block.
  // This is a simplified extraction: find '{' and '}' to get the content.
  // A more robust parser would parse the JS code itself.
  let jsBlockStart = sourceText.indexOf('{', actionParseOutcome.newOffset);
  if (jsBlockStart === -1) return null;
  let jsBlockEnd = sourceText.indexOf('}', jsBlockStart + 1);
  if (jsBlockEnd === -1) return null;

  const rawJsCode = sourceText.substring(jsBlockStart + 1, jsBlockEnd).trim();
  actionParseOutcome.newOffset = jsBlockEnd + 1; // Move past the closing brace.

  // Step 4: Generate the JavaScript code to execute the action and set the parsed value.
  actionParseOutcome.parsedValue = `  if (currentParseResult) { currentParseResult.parsedValue = (() => { ${rawJsCode} })(); }\n`;

  return actionParseOutcome;
}

/**
 * Parses a single term within a grammar rule's expression.
 * A term can be a labeled expression, a non-terminal reference, a string literal,
 * a negated expression, or a parenthesized expression.
 * This function tries each alternative in a defined order.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object if a term is found, otherwise null.
 */
function parseExpressionTerm(sourceText, currentOffset) {
  let termOutcome = null;

  // Try parsing alternatives in a specific order.
  // 1. Labeled expression (e.g., `label: 'foo'`)
  termOutcome = parseLabeledExpression(sourceText, currentOffset);
  if (termOutcome) return termOutcome;

  // 2. Non-terminal reference (e.g., `anotherRule`)
  termOutcome = parseNonTerminalReference(sourceText, currentOffset);
  if (termOutcome) return termOutcome;

  // 3. String literal (e.g., `'keyword'`)
  termOutcome = parseStringLiteral(sourceText, currentOffset);
  if (termOutcome) return termOutcome;

  // 4. Negated expression (e.g., `!'forbidden'`)
  termOutcome = parseNegatedExpression(sourceText, currentOffset);
  if (termOutcome) return termOutcome;

  // 5. Parenthesized expression (e.g., `( 'a' / 'b' )`)
  termOutcome = parseGroupedExpression(sourceText, currentOffset);
  if (termOutcome) return termOutcome;

  // If no term matched any of the alternatives.
  return null;
}

/**
 * Parses a sequence of terms within a grammar rule.
 * This can be one or more terms, optionally followed by a result expression.
 * If no terms or result expression are found, it matches an empty sequence (epsilon).
 * This function uses an iterative approach to consume terms.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome} A ParsingOutcome object with the generated JS code, always successful (can be empty string).
 */
function parseExpressionSequence(sourceText, currentOffset) {
  let sequenceCodeFragments = [];
  let tempCurrentPos = currentOffset;
  let termParseOutcome;

  // Iteratively consume terms as long as they are found.
  while (true) {
    termParseOutcome = parseExpressionTerm(sourceText, tempCurrentPos);
    if (termParseOutcome) {
      sequenceCodeFragments.push(termParseOutcome.parsedValue);
      tempCurrentPos = termParseOutcome.newOffset;
    } else {
      break; // No more terms in the sequence.
    }
  }

  let finalSequenceOutcome = { newOffset: tempCurrentPos, parsedValue: '' };
  let backtrackIfResultFails = [];

  // After consuming all possible terms, try to parse an optional result expression.
  backtrackIfResultFails.push({ newOffset: tempCurrentPos }); // Save state before trying result expression.
  let resultExpressionOutcome = parseResultAction(sourceText, tempCurrentPos);

  if (resultExpressionOutcome) {
    sequenceCodeFragments.push(resultExpressionOutcome.parsedValue);
    finalSequenceOutcome.newOffset = resultExpressionOutcome.newOffset;
    backtrackIfResultFails.pop(); // Result expression succeeded, discard checkpoint.
  } else {
    // Result expression failed or was not present. Restore position (no change needed as it was already tempCurrentPos).
    backtrackIfResultFails.pop(); // Discard the checkpoint.
  }

  // Join all the generated code fragments for the sequence.
  finalSequenceOutcome.parsedValue = sequenceCodeFragments.join('');

  // A sequence is always successful, even if it's empty (epsilon).
  return finalSequenceOutcome;
}

/**
 * Processes a sequence of choices (alternatives) within a grammar rule's body.
 * This generates JavaScript code that attempts to parse each alternative in order.
 * @param {string} sourceText The input string.
 * @param {number} currentOffset The current parsing offset.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the generated JS code, or null on failure.
 */
function processRuleBodyChoices(sourceText, currentOffset) {
  let choiceParseOutcome = { newOffset: currentOffset, parsedValue: undefined };
  let alternativeBacktrackPoints = [];

  // --- Alternative 1: A sequence followed by '/' and another choice (recursive case). ---
  alternativeBacktrackPoints.push({ newOffset: choiceParseOutcome.newOffset }); // Save state for Alternative 2.

  let firstSequenceOutcome = parseExpressionSequence(sourceText, choiceParseOutcome.newOffset);
  if (firstSequenceOutcome) {
    const firstSequenceCode = firstSequenceOutcome.parsedValue;
    choiceParseOutcome.newOffset = firstSequenceOutcome.newOffset;

    let slashSeparatorMatch = matchLiteralString(sourceText, choiceParseOutcome.newOffset, '/');
    if (slashSeparatorMatch) {
      choiceParseOutcome.newOffset = slashSeparatorMatch.newOffset;

      let wsAfterSlash = consumeZeroOrMoreWhitespace(sourceText, choiceParseOutcome.newOffset);
      choiceParseOutcome.newOffset = wsAfterSlash.newOffset;

      let recursiveChoiceOutcome = processRuleBodyChoices(sourceText, choiceParseOutcome.newOffset);
      if (recursiveChoiceOutcome) {
        const remainingChoiceCode = recursiveChoiceOutcome.parsedValue;
        choiceParseOutcome.newOffset = recursiveChoiceOutcome.newOffset;

        // Generate JS for 'OR' logic: try the first sequence, if it fails, try the rest.
        choiceParseOutcome.parsedValue = `  choiceBacktrackStack.push({ newOffset: currentParseResult.newOffset, parsedValue: currentParseResult.parsedValue });\n` +
                                        `  ${firstSequenceCode}\n` +
                                        `  if (!currentParseResult) {\n` +
                                        `    currentParseResult = choiceBacktrackStack.pop();\n` +
                                        `    ${remainingChoiceCode}` +
                                        `  } else { choiceBacktrackStack.pop(); }\n`;
        alternativeBacktrackPoints.pop(); // Alternative 1 succeeded, discard its checkpoint.
        return choiceParseOutcome; // Return immediately on success.
      }
    }
  }

  // If Alternative 1 failed, backtrack and try Alternative 2.
  choiceParseOutcome = alternativeBacktrackPoints.pop(); // Restore to initial offset.

  // --- Alternative 2: Just a single sequence. ---
  let singleSequenceOutcome = parseExpressionSequence(sourceText, choiceParseOutcome.newOffset);
  if (singleSequenceOutcome) {
    choiceParseOutcome.parsedValue = singleSequenceOutcome.parsedValue;
    choiceParseOutcome.newOffset = singleSequenceOutcome.newOffset;
    return choiceParseOutcome; // Alternative 2 succeeded.
  }

  // If both alternatives failed.
  return null;
}

/**
 * Processes a single grammar rule definition.
 * A rule consists of a name, followed by '<-', then a choice expression, and ends with '.'.
 * @param {string} sourceText The input grammar definition string.
 * @param {number} currentOffset The starting position for parsing this rule.
 * @returns {ParsingOutcome|null} A ParsingOutcome object containing the generated JavaScript function string on success, or null on failure.
 */
function processGrammarRule(sourceText, currentOffset) {
  // Initialize parsing outcome for this rule.
  let ruleOutcome = { newOffset: currentOffset, parsedValue: undefined };

  // Basic guard clause for input validity.
  if (currentOffset < 0 || currentOffset > sourceText.length) {
    return null;
  }

  // Step 1: Parse the rule name (identifier).
  let nameResult = extractIdentifier(sourceText, ruleOutcome.newOffset);
  if (!nameResult) return null;
  const ruleIdentifier = nameResult.parsedValue;
  ruleOutcome.newOffset = nameResult.newOffset;

  // Step 2: Consume optional whitespace after the rule name.
  let wsAfterName = consumeZeroOrMoreWhitespace(sourceText, ruleOutcome.newOffset);
  ruleOutcome.newOffset = wsAfterName.newOffset;

  // Step 3: Match the rule assignment operator '<-'.
  let assignmentOpResult = matchLiteralString(sourceText, ruleOutcome.newOffset, '<-');
  if (!assignmentOpResult) return null;
  ruleOutcome.newOffset = assignmentOpResult.newOffset;

  // Step 4: Consume optional whitespace after the assignment operator.
  let wsAfterOp = consumeZeroOrMoreWhitespace(sourceText, ruleOutcome.newOffset);
  ruleOutcome.newOffset = wsAfterOp.newOffset;

  // Step 5: Parse the rule body, which is a choice expression.
  let bodyResult = processRuleBodyChoices(sourceText, ruleOutcome.newOffset);
  if (!bodyResult) return null;
  const ruleBodyJsCode = bodyResult.parsedValue;
  ruleOutcome.newOffset = bodyResult.newOffset;

  // Step 6: Match the rule terminator '.'.
  let terminatorResult = matchLiteralString(sourceText, ruleOutcome.newOffset, '.');
  if (!terminatorResult) return null;
  ruleOutcome.newOffset = terminatorResult.newOffset;

  // Step 7: Consume optional whitespace after the terminator.
  let wsAfterTerminator = consumeZeroOrMoreWhitespace(sourceText, ruleOutcome.newOffset);
  ruleOutcome.newOffset = wsAfterTerminator.newOffset;

  // Step 8: Construct the complete JavaScript function string for this grammar rule.
  ruleOutcome.parsedValue = `function parse_${ruleIdentifier}(sourceText, startOffset) {
  // Initialize parsing context for this rule.
  let currentParseResult = { newOffset: startOffset, parsedValue: undefined };
  let choiceBacktrackStack = []; // For managing 'OR' choices within this rule.

  ${ruleBodyJsCode} // Insert the generated code for the rule's body.

  // Return the final result of this rule's parsing attempt.
  return currentParseResult;
}
`;

  return ruleOutcome;
}

/**
 * Generates the complete parser code from a sequence of grammar rules.
 * This function handles the recursive parsing of multiple rules and appends
 * necessary utility functions at the end of the generated parser output.
 * @param {string} grammarInput The full grammar definition string.
 * @param {number} currentOffset The starting position for parsing.
 * @returns {ParsingOutcome|null} A ParsingOutcome object with the complete generated parser code, or null on failure.
 */
function generateFullParser(grammarInput, currentOffset) {
  let finalParserOutcome = { newOffset: currentOffset, parsedValue: undefined };
  let choiceAlternativesBacktrack = [];

  // --- Alternative 1: Parse a rule followed by more rules (recursive case). ---
  choiceAlternativesBacktrack.push({ newOffset: finalParserOutcome.newOffset });

  let wsBeforeFirstRule = consumeZeroOrMoreWhitespace(grammarInput, finalParserOutcome.newOffset);
  finalParserOutcome.newOffset = wsBeforeFirstRule.newOffset;

  let currentRuleResult = processGrammarRule(grammarInput, finalParserOutcome.newOffset);
  if (currentRuleResult) {
    const currentRuleFunctionCode = currentRuleResult.parsedValue;
    finalParserOutcome.newOffset = currentRuleResult.newOffset;

    let subsequentRulesResult = generateFullParser(grammarInput, finalParserOutcome.newOffset);
    if (subsequentRulesResult) {
      const subsequentRulesCode = subsequentRulesResult.parsedValue;
      finalParserOutcome.newOffset = subsequentRulesResult.newOffset;
      finalParserOutcome.parsedValue = currentRuleFunctionCode + "\n" + subsequentRulesCode;
      choiceAlternativesBacktrack.pop(); // Success, discard checkpoint.
      return finalParserOutcome;
    }
  }

  // If Alternative 1 failed, backtrack and try Alternative 2.
  finalParserOutcome = choiceAlternativesBacktrack.pop(); // Restore to initial position.

  // --- Alternative 2: Parse a single rule and append the core utility functions. ---
  let wsBeforeLastRule = consumeZeroOrMoreWhitespace(grammarInput, finalParserOutcome.newOffset);
  finalParserOutcome.newOffset = wsBeforeLastRule.newOffset;

  let lastRuleResult = processGrammarRule(grammarInput, finalParserOutcome.newOffset);
  if (lastRuleResult) {
    const lastRuleFunctionCode = lastRuleResult.parsedValue;
    finalParserOutcome.newOffset = lastRuleResult.newOffset;

    // Define the core utility functions that are part of the generated parser.
    const coreParserUtilities = `
/**
 * Represents the outcome of a parsing attempt within the generated parser.
 * @typedef {object} GeneratedParsingOutcome
 * @property {number} newOffset - The position in the source text after a successful parse.
 * @property {*} parsedValue - The value extracted or generated by the parser.
 */

/**
 * Parses a single character from the input string.
 * @param {string} sourceText The input string.
 * @param {number} offset The current parsing offset.
 * @returns {GeneratedParsingOutcome|null} A GeneratedParsingOutcome object with the character, or null if at end of input.
 */
function parseCharacter(sourceText, offset) {
  if (offset >= sourceText.length) {
    return null;
  }
  return { newOffset: offset + 1, parsedValue: sourceText.charAt(offset) };
}

/**
 * Matches a specific literal string at the current position.
 * @param {string} sourceText The input string.
 * @param {number} offset The current parsing offset.
 * @param {string} targetString The string to match.
 * @returns {GeneratedParsingOutcome|null} A GeneratedParsingOutcome object with the matched string, or null if no match.
 */
function matchLiteralString(sourceText, offset, targetString) {
  if (sourceText.substring(offset, offset + targetString.length) === targetString) {
    return { newOffset: offset + targetString.length, parsedValue: targetString };
  } else {
    return null;
  }
}

// Export the main parser generation function if in a Node.js environment.
if (typeof exports !== 'undefined') {
  exports.generateFullParser = generateFullParser;
}
`;
    finalParserOutcome.parsedValue = lastRuleFunctionCode + "\n" + coreParserUtilities;
    return finalParserOutcome;
  }

  // If no rules could be parsed at all.
  return null;
}